SELECT log_id::bigint AS "logId",user_id AS "userId",to_char(act_dttm,'YYYY-MM-DD HH24:MI') AS "actedAt",
  act_type_cd AS "actionType",COALESCE(scrn_id,'') AS "screenId",COALESCE(trgt_desc,'') AS "targetDescription"
FROM tb_sy_accs_log WHERE user_id=#{userId} ORDER BY act_dttm DESC,log_id DESC LIMIT #{size} OFFSET #{offset}
